#!/usr/bin/env node
// Generates platform token files from shared/design/tokens.json.
//
//   node scripts/gen-tokens.mjs            write generated files
//   node scripts/gen-tokens.mjs --check    fail if generated files are out of date (CI)
//   node scripts/gen-tokens.mjs --target kotlin|swift
//
// Targets:
//   css     web/src/styles/tokens.css and web/src/styles/tokens.ts (implemented, Phase 0)
//   kotlin  android/app/src/main/java/app/shareanywhere/ui/theme/Tokens.kt (hook, implemented in Phase 6)
//   swift   ios/ShareAnywhereCore/Sources/DesignTokens/Tokens.swift (hook, implemented in Phase 7)
import { readFileSync, writeFileSync, mkdirSync, realpathSync } from 'node:fs';
import { pathToFileURL } from 'node:url';
import { dirname, join, relative } from 'node:path';
import { ROOT, loadTokens, validateTokens, checkContrast } from './lib/tokens.mjs';

const HEADER = 'Generated by scripts/gen-tokens.mjs from shared/design/tokens.json. Do not edit.';

export function renderCss(t) {
  const lines = [`/* ${HEADER} */`, ''];
  const shared = [];
  for (const [k, v] of Object.entries(t.brand)) shared.push(`  --sa-brand-${k}: ${v};`);
  shared.push(`  --sa-font-sans: ${t.font.family.sans};`);
  shared.push(`  --sa-font-mono: ${t.font.family.mono};`);
  for (const [k, v] of Object.entries(t.font.weight)) shared.push(`  --sa-font-weight-${k}: ${v};`);
  for (const [k, [size, lh]] of Object.entries(t.font.size)) {
    shared.push(`  --sa-text-${k}: ${size};`);
    shared.push(`  --sa-leading-${k}: ${lh};`);
  }
  for (const [k, v] of Object.entries(t.space)) shared.push(`  --sa-space-${k}: ${v};`);
  for (const [k, v] of Object.entries(t.radius)) shared.push(`  --sa-radius-${k}: ${v};`);
  for (const [k, v] of Object.entries(t.border)) shared.push(`  --sa-border-${k}: ${v};`);
  for (const [k, v] of Object.entries(t.motion.duration)) shared.push(`  --sa-duration-${k}: ${v};`);
  for (const [k, v] of Object.entries(t.motion.easing)) shared.push(`  --sa-easing-${k}: ${v};`);
  shared.push(`  --sa-touch-target: ${t.touchTarget.web};`);

  const theme = (name) => [
    ...Object.entries(t.color[name]).map(([k, v]) => `  --sa-color-${k}: ${v};`),
    ...Object.entries(t.elevation[name]).map(([k, v]) => `  --sa-elevation-${k}: ${v};`),
    `  color-scheme: ${name};`,
  ];

  lines.push(':root {', ...shared, ...theme('light'), '}', '');
  lines.push('@media (prefers-color-scheme: dark) {', '  :root:not([data-theme="light"]) {');
  lines.push(...theme('dark').map((l) => `  ${l}`), '  }', '}', '');
  lines.push(':root[data-theme="dark"] {', ...theme('dark'), '}', '');
  lines.push('@media (prefers-reduced-motion: reduce) {', '  :root {');
  for (const k of Object.keys(t.motion.duration)) lines.push(`    --sa-duration-${k}: 0ms;`);
  lines.push('  }', '}', '');
  return lines.join('\n');
}

export function renderTs(t) {
  const colorNames = Object.keys(t.color.light);
  return [
    `// ${HEADER}`,
    '',
    `export const colorTokens = ${JSON.stringify(colorNames)} as const;`,
    `export type ColorToken = (typeof colorTokens)[number];`,
    `export const brand = ${JSON.stringify(t.brand)} as const;`,
    `export const fontSizes = ${JSON.stringify(t.font.size)} as const;`,
    `export const space = ${JSON.stringify(t.space)} as const;`,
    `export const radius = ${JSON.stringify(t.radius)} as const;`,
    `export const breakpoints = ${JSON.stringify(t.breakpoint)} as const;`,
    `export const elevationLevels = ${JSON.stringify(Object.keys(t.elevation.light))} as const;`,
    `export const palettes = ${JSON.stringify(t.color)} as const;`,
    `/** Every CSS custom property the generator emits; used by tests. */`,
    `export const cssVariables = ${JSON.stringify(cssVariableNames(t))} as const;`,
    '',
  ].join('\n');
}

export function cssVariableNames(t) {
  return [
    ...Object.keys(t.brand).map((k) => `--sa-brand-${k}`),
    '--sa-font-sans',
    '--sa-font-mono',
    ...Object.keys(t.font.weight).map((k) => `--sa-font-weight-${k}`),
    ...Object.keys(t.font.size).flatMap((k) => [`--sa-text-${k}`, `--sa-leading-${k}`]),
    ...Object.keys(t.space).map((k) => `--sa-space-${k}`),
    ...Object.keys(t.radius).map((k) => `--sa-radius-${k}`),
    ...Object.keys(t.border).map((k) => `--sa-border-${k}`),
    ...Object.keys(t.motion.duration).map((k) => `--sa-duration-${k}`),
    ...Object.keys(t.motion.easing).map((k) => `--sa-easing-${k}`),
    '--sa-touch-target',
    ...Object.keys(t.color.light).map((k) => `--sa-color-${k}`),
    ...Object.keys(t.elevation.light).map((k) => `--sa-elevation-${k}`),
  ];
}

const TARGETS = {
  css: (t) => [
    [join(ROOT, 'web/src/styles/tokens.css'), renderCss(t)],
    [join(ROOT, 'web/src/styles/tokens.ts'), renderTs(t)],
  ],
  kotlin: () => {
    throw new Error('Kotlin token generation is implemented in Phase 6 (Android). See docs/phases/PHASE_6_ANDROID.md.');
  },
  swift: () => {
    throw new Error('Swift token generation is implemented in Phase 7 (iOS). See docs/phases/PHASE_7_IOS.md.');
  },
};

function main(argv) {
  const check = argv.includes('--check');
  const ti = argv.indexOf('--target');
  const targets = ti >= 0 ? [argv[ti + 1]] : ['css'];
  const tokens = loadTokens();

  const schemaErrors = validateTokens(tokens);
  if (schemaErrors.length) {
    console.error('tokens.json does not match tokens.schema.json:\n  ' + schemaErrors.join('\n  '));
    process.exit(1);
  }
  const contrast = checkContrast(tokens);
  if (contrast.length) {
    console.error('Contrast check failed (WCAG AA):\n  ' + contrast.join('\n  '));
    process.exit(1);
  }

  let stale = 0;
  for (const target of targets) {
    if (!TARGETS[target]) {
      console.error(`Unknown target "${target}". Known: ${Object.keys(TARGETS).join(', ')}`);
      process.exit(1);
    }
    for (const [file, content] of TARGETS[target](tokens)) {
      const rel = relative(ROOT, file);
      if (check) {
        let current = '';
        try {
          current = readFileSync(file, 'utf8');
        } catch {
          /* missing file counts as stale */
        }
        if (current !== content) {
          console.error(`Out of date: ${rel}. Run "pnpm tokens".`);
          stale++;
        }
      } else {
        mkdirSync(dirname(file), { recursive: true });
        writeFileSync(file, content);
        console.log(`wrote ${rel}`);
      }
    }
  }
  if (stale) process.exit(1);
  if (check) console.log('Design tokens: schema valid, contrast AA, generated files current.');
}

// Run main() only when executed directly (robust to spaces, symlinks, and Windows paths).
const invokedPath = process.argv[1] ? pathToFileURL(realpathSync(process.argv[1])).href : '';
if (import.meta.url === invokedPath) main(process.argv.slice(2));
